'use client'
import { motion } from 'framer-motion'
import { useCallback, useState } from "react"
import Particles from "react-tsparticles"
import { loadSlim } from "tsparticles-slim"
import { useTheme } from '../context/ThemeContext'
import { FaGithub, FaLinkedin, FaEnvelope, FaPhone } from 'react-icons/fa'
import emailjs from '@emailjs/browser';
import toast from 'react-hot-toast';



export default function Contact() {
  const { isDark, theme } = useTheme()
  const [isLoading, setIsLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  })

  const particlesInit = useCallback(async engine => {
    await loadSlim(engine)
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    setIsLoading(true)
    
    try {
      await emailjs.send(
        'YOUR_SERVICE_ID',    // Get from EmailJS dashboard
        'YOUR_TEMPLATE_ID',   // Get from EmailJS dashboard
        {
          from_name: formData.name,
          from_email: formData.email,
          message: formData.message,
          to_email: 'sebasalamah00@gmail.com',
        },
        'YOUR_PUBLIC_KEY'     // Get from EmailJS dashboard
      )
  
      setFormData({ name: '', email: '', message: '' })
      toast.success('Message sent successfully! 🎉')
    } catch (error) {
      toast.error('Oops! Something went wrong 🤔')
    } finally {
      setIsLoading(false)
    }
  }

  const socialLinks = [
    {
      icon: FaGithub,
      href: "https://github.com/Seba-00",
      label: "GitHub"
    },
    {
      icon: FaLinkedin,
      href: "https://linkedin.com/in/seba-salamah",
      label: "LinkedIn"
    },
    {
      icon: FaEnvelope,
      href: "mailto:sebasalamah00@gmail.com",
      label: "sebasalamah00@gmail.com"
    },
    {
      icon: FaPhone,
      href: "tel:+966555948067",
      label: "+966 555 948 067"
    }
  ]

  return (
    <section className={`min-h-screen flex items-center justify-center bg-gradient-to-br ${theme.bg} relative overflow-hidden transition-all duration-700 py-20`}>
      <Particles
        id="tsparticles-contact"
        init={particlesInit}
        options={{
          background: { color: { value: "transparent" } },
          fpsLimit: 120,
          interactivity: {
            events: {
              onHover: { enable: true, mode: "repulse" },
              onClick: { enable: true, mode: "push" },
            },
            modes: {
              repulse: { distance: 100, duration: 0.4 },
              push: { quantity: 4 },
            },
          },
          particles: {
            color: { value: [theme.primary, theme.secondary, theme.accent] },
            links: {
              color: theme.primary,
              distance: 150,
              enable: true,
              opacity: 0.5,
              width: 1,
            },
            move: {
              direction: "none",
              enable: true,
              outModes: { default: "bounce" },
              random: false,
              speed: 2,
              straight: false,
            },
            number: {
              density: { enable: true, area: 800 },
              value: 80,
            },
            opacity: {
              value: 0.5,
              animation: {
                enable: true,
                speed: 1,
                minimumValue: 0.1,
              },
            },
            shape: { type: "circle" },
            size: { value: { min: 1, max: 3 } },
          },
          detectRetina: true,
        }}
      />

      <div className="container mx-auto px-4 z-10">
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <h2 className="font-mono mb-4" style={{ color: theme.primary }}>
            Get In Touch
          </h2>
          <h3 className="text-4xl font-bold" style={{ color: theme.text }}>
            Let's Connect
          </h3>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-12 max-w-6xl mx-auto">
          {/* Social Links */}
          <motion.div
            initial={{ x: -100, opacity: 0 }}
            whileInView={{ x: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
            className="space-y-8"
          >
            <h4 
              className="text-2xl font-bold mb-8"
              style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
            >
              Connect With Me
            </h4>
            
            {socialLinks.map((link, index) => (
              <motion.a
                key={link.label}
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-4 group"
                whileHover={{ x: 10 }}
                initial={{ opacity: 0, x: -50 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.1 }}
              >
                <div 
                  className="w-12 h-12 rounded-full flex items-center justify-center"
                  style={{ 
                    backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
                    color: isDark ? '#bd93f9' : '#EDAFB8'
                  }}
                >
                  <link.icon className="w-6 h-6" />
                </div>
                <span 
                  className="text-lg group-hover:underline"
                  style={{ color: theme.textSecondary }}
                >
                  {link.label}
                </span>
              </motion.a>
            ))}
          </motion.div>

          {/* Contact Form */}
          <motion.div
            initial={{ x: 100, opacity: 0 }}
            whileInView={{ x: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
            className="backdrop-blur-lg rounded-xl p-8"
            style={{
              backgroundColor: isDark ? 'rgba(10, 25, 47, 0.7)' : 'rgba(255, 255, 255, 0.7)',
              borderColor: theme.primary,
              borderWidth: '1px'
            }}
          >
            <form onSubmit={handleSubmit} className="space-y-6">
              <div>
                <label 
                  htmlFor="name"
                  className="block mb-2"
                  style={{ color: theme.text }}
                >
                  Name
                </label>
                <input
                  type="text"
                  id="name"
                  className="w-full px-4 py-2 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
                  style={{
                    backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
                    color: theme.text,
                    borderColor: theme.primary,
                    borderWidth: '1px'
                  }}
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                />
              </div>

              <div>
                <label 
                  htmlFor="email"
                  className="block mb-2"
                  style={{ color: theme.text }}
                >
                  Email
                </label>
                <input
                  type="email"
                  id="email"
                  className="w-full px-4 py-2 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
                  style={{
                    backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
                    color: theme.text,
                    borderColor: theme.primary,
                    borderWidth: '1px'
                  }}
                  value={formData.email}
                  onChange={(e) => setFormData({...formData, email: e.target.value})}
                />
              </div>

              <div>
                <label 
                  htmlFor="message"
                  className="block mb-2"
                  style={{ color: theme.text }}
                >
                  Message
                </label>
                <textarea
                  id="message"
                  rows={5}
                  className="w-full px-4 py-2 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
                  style={{
                    backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
                    color: theme.text,
                    borderColor: theme.primary,
                    borderWidth: '1px'
                  }}
                  value={formData.message}
                  onChange={(e) => setFormData({...formData, message: e.target.value})}
                />
              </div>

              <motion.button
                type="submit"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="w-full py-3 rounded-lg font-bold transition-all duration-300"
                style={{
                  backgroundColor: isDark ? '#bd93f9' : '#EDAFB8',
                  color: isDark ? '#0a192f' : '#ffffff'
                }}
              >
                Send Message
              </motion.button>
            </form>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

