'use client'
import { motion } from 'framer-motion'
import { useCallback } from "react"
import Particles from "react-tsparticles"
import { loadSlim } from "tsparticles-slim"
import { useTheme } from '../context/ThemeContext'
import { DiReact, DiJavascript1, DiPython, DiNodejs } from 'react-icons/di'
import { SiTypescript, SiNextdotjs, SiTailwindcss, SiMongodb, SiPostgresql, SiFigma } from 'react-icons/si'

export default function Skills() {
  const { isDark, theme } = useTheme()

  const particlesInit = useCallback(async engine => {
    await loadSlim(engine)
  }, [])

  const skillsData = [
    {
      category: "Frontend",
      icon: DiReact,
      items: [
        { name: "React", icon: DiReact, proficiency: 90 },
        { name: "Next.js", icon: SiNextdotjs, proficiency: 85 },
        { name: "JavaScript", icon: DiJavascript1, proficiency: 95 },
        { name: "TypeScript", icon: SiTypescript, proficiency: 80 },
        { name: "TailwindCSS", icon: SiTailwindcss, proficiency: 90 },
      ]
    },
    {
      category: "Backend",
      icon: DiNodejs,
      items: [
        { name: "Node.js", icon: DiNodejs, proficiency: 85 },
        { name: "Python", icon: DiPython, proficiency: 80 },
        { name: "MongoDB", icon: SiMongodb, proficiency: 75 },
        { name: "PostgreSQL", icon: SiPostgresql, proficiency: 70 },
      ]
    },
    {
      category: "Design",
      icon: SiFigma,
      items: [
        { name: "Figma", icon: SiFigma, proficiency: 85 },
      ]
    }
  ]

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.3
      }
    }
  }

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.5
      }
    }
  }

  return (
    <section id="skills" className="min-h-screen relative overflow-hidden py-20">
      {/* Animated background gradient */}
      <div 
        className="fixed inset-0 transition-all duration-1000"
        style={{
          background: isDark 
            ? 'radial-gradient(circle at 50% 50%, #1a1b2c 0%, #0f1016 100%)'
            : 'radial-gradient(circle at 50% 50%, #ffffff 0%, #f3f4f6 100%)'
        }}
      />

      {/* Floating particles effect */}
      <Particles
        id="tsparticles-skills"
        init={particlesInit}
        options={{
          background: { color: { value: "transparent" } },
          fpsLimit: 120,
          particles: {
            color: { value: isDark ? "#bd93f9" : "#EDAFB8" },
            links: {
              color: isDark ? "#bd93f9" : "#EDAFB8",
              distance: 150,
              enable: true,
              opacity: 0.3,
              width: 1,
            },
            move: {
              enable: true,
              speed: 1,
              direction: "none",
              random: true,
              straight: false,
              outModes: { default: "bounce" },
            },
            number: { density: { enable: true, area: 1000 }, value: 40 },
            opacity: { value: 0.3 },
            size: { value: { min: 1, max: 3 } },
          },
        }}
      />
      
      <div className="container mx-auto px-4 relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <motion.span 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2 }}
            className="inline-block px-4 py-2 rounded-full text-sm font-medium mb-4"
            style={{
              background: isDark ? 'rgba(189,147,249,0.1)' : 'rgba(237,175,184,0.1)',
              color: isDark ? '#bd93f9' : '#EDAFB8'
            }}
          >
            What I Do
          </motion.span>
          
          <motion.h2 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="text-4xl font-bold"
            style={{ color: theme.text }}
          >
            My Expertise
          </motion.h2>
        </motion.div>

        <motion.div 
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          className="grid grid-cols-1 md:grid-cols-3 gap-8"
        >
          {skillsData.map((category, categoryIndex) => (
            <motion.div
              key={category.category}
              variants={itemVariants}
              className="group"
            >
              <motion.div
                whileHover={{ scale: 1.02 }}
                className="backdrop-blur-lg rounded-xl p-6 h-full transition-all duration-300"
                style={{
                  backgroundColor: isDark ? 'rgba(26, 27, 44, 0.8)' : 'rgba(255, 255, 255, 0.8)',
                  boxShadow: `0 4px 20px ${isDark ? 'rgba(189,147,249,0.1)' : 'rgba(237,175,184,0.1)'}`,
                  border: `1px solid ${isDark ? 'rgba(189,147,249,0.2)' : 'rgba(237,175,184,0.2)'}`
                }}
              >
                <div className="flex items-center gap-3 mb-6">
                  <category.icon 
                    className="w-8 h-8 transition-transform duration-300 group-hover:rotate-12"
                    style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
                  />
                  <h3 
                    className="text-2xl font-bold"
                    style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
                  >
                    {category.category}
                  </h3>
                </div>

                <div className="space-y-6">
                  {category.items.map((skill, index) => (
                    <motion.div
                      key={skill.name}
                      initial={{ x: -20, opacity: 0 }}
                      whileInView={{ x: 0, opacity: 1 }}
                      transition={{ delay: index * 0.1 }}
                      className="relative"
                    >
                      <div className="flex items-center gap-3 mb-2">
                        <skill.icon 
                          className="w-5 h-5"
                          style={{ color: theme.textSecondary }}
                        />
                        <span style={{ color: theme.text }}>{skill.name}</span>
                      </div>
                      
                      <div className="relative h-2 rounded-full overflow-hidden"
                           style={{ backgroundColor: isDark ? 'rgba(26, 27, 44, 0.8)' : 'rgba(237,175,184,0.1)' }}>
                        <motion.div
                          initial={{ width: 0 }}
                          whileInView={{ width: `${skill.proficiency}%` }}
                          transition={{ duration: 1, delay: index * 0.1 }}
                          className="absolute top-0 left-0 h-full rounded-full"
                          style={{ 
                            backgroundColor: isDark ? '#bd93f9' : '#EDAFB8',
                          }}
                        />
                      </div>
                      
                      <motion.span 
                        initial={{ opacity: 0 }}
                        whileInView={{ opacity: 1 }}
                        className="absolute right-0 top-0 text-sm"
                        style={{ color: theme.textSecondary }}
                      >
                        {skill.proficiency}%
                      </motion.span>
                    </motion.div>
                  ))}
                </div>
              </motion.div>
            </motion.div>
          ))}
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.5 }}
          className="text-center mt-16 max-w-2xl mx-auto"
        >
          <p 
            className="text-lg"
            style={{ color: theme.textSecondary }}
          >
            Always exploring new technologies and pushing creative boundaries ✨
          </p>
        </motion.div>
      </div>
    </section>
  )
}