'use client'

import { motion } from 'framer-motion'
import { FaGithub, FaLinkedin } from 'react-icons/fa'
import { FiSun, FiMoon } from 'react-icons/fi'
import { useState } from "react"
import { TypeAnimation } from 'react-type-animation'
import { useTheme } from '../context/ThemeContext'
import LanguageSwitch from '../components/LanguageSwitch'

const navItems = [
  { title: 'Home', id: 'home' },
  { title: 'Skills', id: 'skills' },
  { title: 'Projects', id: 'projects' },
  { title: 'Contact', id: 'contact' }
]

export default function Hero() {
  const { isDark, toggleTheme, theme } = useTheme()
  const [activeSection, setActiveSection] = useState('home')

  const handleScroll = (id) => {
    const element = document.getElementById(id)
    element?.scrollIntoView({ behavior: 'smooth' })
    setActiveSection(id)
  }

  return (
    <section id="home" className="min-h-screen relative">
      {/* Gradient Background */}
      <div 
        className="fixed inset-0 transition-opacity duration-700"
        style={{
          background: isDark 
            ? 'radial-gradient(circle at 50% 50%, #1a1b2c 0%, #0f1016 100%)'
            : 'radial-gradient(circle at 50% 50%, #ffffff 0%, #f3f4f6 100%)'
        }}
      />
      
      {/* Floating elements in background */}
      <div className="fixed inset-0 overflow-hidden opacity-20">
        <div className="absolute top-1/4 left-1/4 w-32 h-32 rounded-full bg-purple-400 mix-blend-multiply filter blur-xl animate-float"/>
        <div className="absolute top-1/3 right-1/4 w-32 h-32 rounded-full bg-blue-400 mix-blend-multiply filter blur-xl animate-float-delay"/>
      </div>

      {/* Navigation Header */}
      <nav className="fixed top-0 left-0 right-0 z-50 backdrop-blur-sm">
        <div className="max-w-5xl mx-auto px-4">
          <div className="flex items-center justify-between h-20">
            {/* Nav Links */}
            <div className="hidden md:flex gap-8">
              {navItems.map((item) => (
                <motion.button
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="relative py-2"
                  whileHover={{ y: -2 }}
                >
                  <span style={{ 
                    color: activeSection === item.id ? theme.primary : theme.textSecondary 
                  }}>
                    {item.title}
                  </span>
                  {activeSection === item.id && (
                    <motion.div
                      className="absolute bottom-0 left-0 right-0 h-0.5 rounded-full"
                      style={{ backgroundColor: theme.primary }}
                      layoutId="activeSection"
                    />
                  )}
                </motion.button>
              ))}
            </div>

            {/* Social Icons, Language & Theme Toggle */}
            <div className="flex items-center gap-6">
              <motion.a
                href="https://github.com/Seba-00"
                target="_blank"
                rel="noopener noreferrer"
                whileHover={{ y: -2 }}
                className="hover:opacity-80 transition-opacity"
                style={{ color: theme.primary }}
              >
                <FaGithub className="w-5 h-5" />
              </motion.a>

              <motion.a
                href="https://linkedin.com/in/seba-salamah"
                target="_blank"
                rel="noopener noreferrer"
                whileHover={{ y: -2 }}
                className="hover:opacity-80 transition-opacity"
                style={{ color: theme.primary }}
              >
                <FaLinkedin className="w-5 h-5" />
              </motion.a>

              <LanguageSwitch />

              <motion.button
                onClick={toggleTheme}
                whileHover={{ y: -2 }}
                whileTap={{ scale: 0.95 }}
                className="hover:opacity-80 transition-opacity"
                style={{ color: theme.primary }}
              >
                {isDark ? <FiSun className="w-5 h-5" /> : <FiMoon className="w-5 h-5" />}
              </motion.button>
            </div>
          </div>
        </div>
      </nav>
      
      {/* Main Content */}
      <div className="relative z-10 flex items-center justify-center min-h-screen px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-center max-w-2xl"
        >
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2 }}
            className="font-mono mb-3 text-lg"
            style={{ color: theme.primary }}
          >
            Hi there, I'm
          </motion.div>
          
          <motion.h1 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="text-6xl font-bold mb-4"
            style={{ color: theme.text }}
          >
            Seba.
          </motion.h1>
          
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.4 }}
            className="text-3xl font-bold mb-6 h-[48px]"
            style={{ color: theme.textSecondary }}
          >
            <TypeAnimation
              sequence={[
                'Full Stack Developer',
                1500,
                'UI/UX Enthusiast',
                1500,
                'Problem Solver',
                1500,
                'Tech Explorer',
                1500,
              ]}
              wrapper="span"
              speed={50}
              repeat={Infinity}
            />
          </motion.div>

          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className="text-lg"
            style={{ color: theme.textSecondary }}
          >
            Turning coffee into code and dreams into digital reality ✨
          </motion.p>
        </motion.div>
      </div>

      <style jsx>{`
        @keyframes float {
          0% { transform: translate(0, 0) rotate(0deg); }
          50% { transform: translate(20px, 20px) rotate(180deg); }
          100% { transform: translate(0, 0) rotate(360deg); }
        }
        .animate-float {
          animation: float 20s infinite linear;
        }
        .animate-float-delay {
          animation: float 20s infinite linear;
          animation-delay: -10s;
        }
      `}</style>
    </section>
  )
}
